    """Return only validated URLs; invalid or empty values stay disabled."""
    return {
        "game_chat": GAME_CHAT_URL,
        "news_channel": NEWS_CHANNEL_URL,
        "support": SUPPORT_URL,
    }

def get_location_boss_definition(location_id):
    boss_key = BOSS_KEY_BY_LOCATION.get(str(location_id or ""))
    return get_boss_definition(boss_key)

