def validate_stat_system_config() -> tuple[str, ...]:
    problems = []
    expected_classes = set(SUPPORTED_CLASSES)
    expected_stats = set(PRIMARY_STAT_KEYS)
    for label, matrix in (
        ("PHYSICAL_ATTACK_SCALING", PHYSICAL_ATTACK_SCALING),
        ("MAGICAL_ATTACK_SCALING", MAGICAL_ATTACK_SCALING),
    ):
        if set(matrix) != expected_classes:
            problems.append(f"{label}: class set mismatch")
        for class_key, coefficients in matrix.items():
            if set(coefficients) != expected_stats:
                problems.append(f"{label}/{class_key}: stat key mismatch")
            for stat_key, value in coefficients.items():
                if isinstance(value, bool) or not isinstance(value, (int, float)):
                    problems.append(f"{label}/{class_key}/{stat_key}: coefficient must be numeric")
                elif not math.isfinite(float(value)) or float(value) < 0:
                    problems.append(f"{label}/{class_key}/{stat_key}: coefficient must be finite and non-negative")
    if set(MAX_MP_SCALING) != {"base", "level", "int", "wis"}:
        problems.append("MAX_MP_SCALING: key mismatch")
    for key, value in MAX_MP_SCALING.items():
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            problems.append(f"MAX_MP_SCALING/{key}: coefficient must be numeric")
        elif not math.isfinite(float(value)) or float(value) < 0:
            problems.append(f"MAX_MP_SCALING/{key}: coefficient must be finite and non-negative")
    return tuple(problems)

def _definition(row):
 d=row["definition"]; item=d.get("quest_item"); nav=d["navigation"]
 return StoryQuestDefinition(quest_id=d["quest_id"],number=d["number"],title=d["title"],quest_type=QuestType(d["quest_type"]),location_id=d["location_id"],unlock_level=d["unlock_level"],previous_quest_id=d.get("previous_quest_id"),giver_npc_id=d["giver_npc_id"],turn_in_npc_id=d.get("turn_in_npc_id"),description=d["description"],objective_text=d["objective_text"],target_quantity=d["target_quantity"],boss_key=d.get("boss_key"),quest_item=QuestItemDefinition(**item) if item else None,required_quest_items=tuple(RequiredQuestItemDefinition(**x) for x in d.get("required_quest_items",[])),quest_item_consumption=d.get("quest_item_consumption","default"),reward=RewardDefinition(**d["reward"]),navigation=NavigationDefinition(**nav))

def ordered_story_sections(location_id: str) -> tuple[StorySectionMetadata, ...]:
    """Return production sections for one location in stable display order."""
    story = STORY_LOCATIONS.get(location_id)
    if story is None:
        raise KeyError(f"Unknown story location: {location_id}")
    return tuple(sorted((STORY_SECTIONS[section_id] for section_id in story.section_ids), key=lambda section: section.sort_order))

def get_story_location(location_id: str) -> StoryLocationMetadata:
    """Return canonical story metadata or fail closed for an unknown ID."""
    try:
        return STORY_LOCATIONS[location_id]
    except KeyError as exc:
        raise KeyError(f"Unknown story location: {location_id}") from exc

def get_story_section(section_id: str) -> StorySectionMetadata:
    """Return canonical section metadata or fail closed for an unknown ID."""
    try:
        return STORY_SECTIONS[section_id]
    except KeyError as exc:
        raise KeyError(f"Unknown story section: {section_id}") from exc

def get_story_section_for_quest_number(quest_number: int) -> StorySectionMetadata:
    """Resolve exactly one production section for a production quest number."""
    matches = tuple(section for section in STORY_SECTIONS.values() if quest_number in section.quest_numbers)
    if len(matches) != 1:
        raise KeyError(f"Quest {quest_number} belongs to {len(matches)} story sections")
    return matches[0]

def validate_story_hierarchy_metadata() -> dict[str, object]:
    """Validate registry coverage, ordering, localization, and section contracts."""
    production_by_number = {quest.number: quest for quest in STORY_QUEST_REGISTRY.values()}
    production_numbers = tuple(production_by_number)
    metadata_numbers: list[int] = []
    seen_numbers: set[int] = set()

    if tuple(sorted(STORY_LOCATIONS, key=lambda location_id: STORY_LOCATIONS[location_id].sort_order)) != tuple(
        story.story_id for story in ordered_story_locations()
    ):
        raise ValueError("Story location ordering is not stable")

    for story in ordered_story_locations():
        if story.story_id != story.location_id:
            raise ValueError(f"Story ID must equal canonical location ID: {story.story_id}")
        if story.display_name != "Початок Шляху" and story.location_id == "start_path":
            raise ValueError("start_path must resolve to Початок Шляху")
        if story.location_id in story.button_label or "Start Path" in story.button_label:
            raise ValueError("Technical location ID leaked into player-facing story label")
        sections = ordered_story_sections(story.location_id)
        if tuple(section.section_id for section in sections) != story.section_ids:
            raise ValueError(f"Section order mismatch for {story.story_id}")
        expected_section_numbers = tuple(range(1, len(sections) + 1))
        if tuple(section.number for section in sections) != expected_section_numbers:
            raise ValueError(f"Section numbers must be continuous for {story.story_id}")

        for section in sections:
            if section.location_id != story.location_id:
                raise ValueError(f"Section {section.section_id} location mismatch")
            if "глава" in section.display_title.casefold():
                raise ValueError(f"Forbidden Ukrainian term in {section.section_id}")
            if not section.display_title.startswith("Розділ "):
                raise ValueError(f"Invalid section presentation title: {section.display_title}")
            if not section.quest_numbers:
                raise ValueError(f"Empty section: {section.section_id}")
            if section.quest_numbers != tuple(range(section.quest_numbers[0], section.quest_numbers[-1] + 1)):
                raise ValueError(f"Non-contiguous quest range: {section.section_id}")
            for quest_number in section.quest_numbers:
                if quest_number in seen_numbers:
                    raise ValueError(f"Quest {quest_number} belongs to multiple sections")
                seen_numbers.add(quest_number)
                metadata_numbers.append(quest_number)
                quest = production_by_number.get(quest_number)
                if quest is None:
                    raise ValueError(f"Metadata exposes inactive quest {quest_number}")
                if quest.location_id != story.location_id:
                    raise ValueError(f"Quest {quest_number} location mismatch")
                if quest.unlock_level != section.required_level:
                    raise ValueError(f"Quest {quest_number} unlock level mismatch")

    if tuple(metadata_numbers) != production_numbers:
        raise ValueError(
            f"Hierarchy coverage mismatch: metadata={tuple(metadata_numbers)}, production={production_numbers}"
        )

    return {
        "story_ids": tuple(story.story_id for story in ordered_story_locations()),
        "section_ids": tuple(section.section_id for section in STORY_SECTIONS.values()),
        "quest_numbers": tuple(metadata_numbers),
        "production_quest_count": len(production_numbers),
        "metadata_quest_count": len(metadata_numbers),
        "localized_start_path": STORY_LOCATIONS["start_path"].display_name,
        "start_path_button_label": STORY_LOCATIONS["start_path"].button_label,
        "section_titles": tuple(section.display_title for section in ordered_story_sections("start_path")),
    }

def validate_story_quest_item_key(item_key: str) -> str:
    """Return a stable canonical key or reject an inventory-like identity."""
    key = str(item_key or "").strip()
    if not STORY_QUEST_ITEM_KEY_PATTERN.fullmatch(key):
        raise ValueError(
            "story quest item_key must be lowercase snake_case with a namespace prefix"
        )
    return key

def inspect_story_quest_item_schema(connection) -> dict:
    """Inspect SQLite metadata without changing schema or table contents."""
    columns = tuple(
        str(row[1]) for row in connection.execute(
            f"PRAGMA table_info({STORY_QUEST_ITEM_TABLE})"
        ).fetchall()
    )
    column_set = frozenset(columns)
    indexes = connection.execute(
        f"PRAGMA index_list({STORY_QUEST_ITEM_TABLE})"
    ).fetchall()
    unique_column_sets = []
    for row in indexes:
        if not bool(row[2]):
            continue
        name = str(row[1])
        members = tuple(
            str(item[2]) for item in connection.execute(
                f"PRAGMA index_info({name})"
            ).fetchall()
        )
        unique_column_sets.append(members)
    foreign_keys = connection.execute(
        f"PRAGMA foreign_key_list({STORY_QUEST_ITEM_TABLE})"
    ).fetchall()
    return {
        "columns": columns,
        "missing_required": sorted(STORY_QUEST_ITEM_REQUIRED_COLUMNS - column_set),
        "forbidden_present": sorted(STORY_QUEST_ITEM_FORBIDDEN_COLUMNS & column_set),
        "identity_unique": STORY_QUEST_ITEM_IDENTITY_COLUMNS in unique_column_sets,
        "foreign_key_tables": sorted({str(row[2]) for row in foreign_keys}),
        "row_id_semantics": "local_table_row_only",
        "ordinary_items_id_used": False,
    }

def validate_story_quest_item_schema(connection) -> dict:
    """Fail closed if virtual quest items can overlap ordinary inventory identity."""
    result = inspect_story_quest_item_schema(connection)
    errors = []
    if result["missing_required"]:
        errors.append(f"missing columns: {result['missing_required']}")
    if result["forbidden_present"]:
        errors.append(f"forbidden columns: {result['forbidden_present']}")
    if not result["identity_unique"]:
        errors.append("missing UNIQUE(user_id, quest_id, item_key)")
    if "user_story_quests" not in result["foreign_key_tables"]:
        errors.append("missing foreign key to user_story_quests")
    if errors:
        raise RuntimeError("; ".join(errors))
    result["status"] = "PASS"
    return result

def validate_story_quest_npc_registry(
    definitions: tuple[StoryQuestNpcDefinition, ...] = _NPC_DEFINITIONS,
) -> Mapping[str, StoryQuestNpcDefinition]:
    """Validate identities, routes and labels, then return an immutable registry."""
    if not definitions:
        raise StoryQuestNpcRegistryError("NPC registry cannot be empty")
    registry = {}
    button_labels = set()
    for npc in definitions:
        if not npc.npc_id or not npc.npc_id.replace("_", "").isalnum():
            raise StoryQuestNpcRegistryError(f"invalid npc_id: {npc.npc_id!r}")
        if npc.npc_id in registry:
            raise StoryQuestNpcRegistryError(f"duplicate npc_id: {npc.npc_id}")
        if not npc.display_name.strip() or not npc.button_label.strip():
            raise StoryQuestNpcRegistryError(f"missing NPC presentation: {npc.npc_id}")
        if npc.button_label in button_labels:
            raise StoryQuestNpcRegistryError(
                f"duplicate NPC button label: {npc.button_label}"
            )
        if not npc.world_location_id or not npc.city_section_id:
            raise StoryQuestNpcRegistryError(f"missing NPC context: {npc.npc_id}")
        if len(npc.route_labels) < 3:
            raise StoryQuestNpcRegistryError(
                f"NPC route must include city, section and NPC: {npc.npc_id}"
            )
        if npc.route_labels[-1] != npc.button_label:
            raise StoryQuestNpcRegistryError(
                f"route terminal must match button label: {npc.npc_id}"
            )
        registry[npc.npc_id] = npc
        button_labels.add(npc.button_label)
    return MappingProxyType(registry)

def get_story_quest_npc(npc_id: str) -> StoryQuestNpcDefinition:
    """Resolve a stable NPC ID or fail closed for invalid quest content."""
    key = str(npc_id or "").strip()
    try:
        return STORY_QUEST_NPCS[key]
    except KeyError as error:
        raise StoryQuestNpcRegistryError(f"unknown story quest NPC: {key}") from error

def validate_story_quest_npc_references(
    *, giver_npc_id: str, turn_in_npc_id: Optional[str] = None,
) -> None:
    """Validate the stable NPC references used by one quest definition."""
    giver = get_story_quest_npc(giver_npc_id)
    if not giver.can_give_quests:
        raise StoryQuestNpcRegistryError(
            f"NPC cannot give quests: {giver.npc_id}"
        )
    if turn_in_npc_id is not None:
        receiver = get_story_quest_npc(turn_in_npc_id)
        if not receiver.can_receive_turn_in:
            raise StoryQuestNpcRegistryError(
                f"NPC cannot receive quest turn-in: {receiver.npc_id}"
            )

def get_node_name(node_id, world_nodes):
    """Return a localized canonical name and never expose a raw technical ID."""
    return (world_nodes.get(str(node_id)) or {}).get("name") or UNKNOWN_LOCATION_NAME

def get_route_presentation(from_node, to_node):
    """Return approved route metadata or safe generic text for an unknown edge."""
    return ROUTE_PRESENTATION.get((str(from_node), str(to_node)), {
        "preview": "Попереду дорога до обраного пункту призначення.",
        "active": "Подорож триває за обраним маршрутом.",
        "arrival": "Подорож завершено, і перед тобою відкривається нова місцевість.",
    })

