        except Exception:
            pass

    durability = snapshot.get("durability")
    max_durability = snapshot.get("max_durability")
    if durability is not None:
        lines.append(
            f"🧱 Міцність: {durability}/{max_durability if max_durability is not None else 100}"
        )

    physical_min = int(snapshot.get("weapon_min_damage") or 0)
    physical_max = int(snapshot.get("weapon_max_damage") or 0)
    magic_min = int(snapshot.get("weapon_min_magic_damage") or 0)
    magic_max = int(snapshot.get("weapon_max_magic_damage") or 0)
    if physical_min or physical_max:
        from systems.equipment_system import get_effective_weapon_display_range_17_18_2_5
        physical_min, physical_max = get_effective_weapon_display_range_17_18_2_5(
            physical_min,
            physical_max,
            snapshot.get("item_subtype"),
        )
    if physical_min or physical_max:
        lines.append(f"⚔️ Фізична шкода: {physical_min}-{physical_max}")
    if magic_min or magic_max:
        lines.append(f"🔮 Магічна шкода: {magic_min}-{magic_max}")

    stat_labels = {
        "bonus_str": "💪 Сила",
        "bonus_dex": "🎯 Спритність",
        "bonus_int": "🔮 Інтелект",
        "bonus_wis": "🦉 Мудрість",
        "bonus_sta": "🛡 Витривалість",
        "pdef": "🛡 Фіз. захист",
        "mdef": "🔮 Маг. захист",
    }
    bonuses = []
    for key, label in stat_labels.items():
        value = int(snapshot.get(key) or 0)
        if value:
            bonuses.append(f"• {label} +{value}")
    lines.extend(["", "📊 Бонуси:"])
    lines.extend(bonuses or ["• немає"])

    inventory_id = snapshot.get("inventory_id")
    if owner_id is not None and inventory_id is not None:
        try:
            from systems.rune_system import format_equipment_rune_slots_text
            rune_block = format_equipment_rune_slots_text(int(owner_id), int(inventory_id)).strip()
            if rune_block:
                lines.extend(["", *rune_block.splitlines()])
        except Exception:
            pass
    return lines

def _install_player_trade_handler_level_navigation_guard_12_6_6(bot):
    """Install first-priority TeleBot handlers instead of wrapping dispatcher.

    The persistent trade status button is consumed by a normal no-op message
    handler. Active-trade message/callback guards return ContinueHandling for
    permitted updates, preserving TeleBot's ordinary dispatch lifecycle.
    """
    if getattr(bot, "_rom_trade_handler_level_guard_12_6_6", False):
        return {"success": True, "installed": False}

    from telebot.handler_backends import ContinueHandling
    import time

    notice_at = {}

    def notice_allowed(user_id):
        uid = int(user_id)
        now = time.monotonic()
        previous = float(notice_at.get(uid, -10**9))
        if now - previous < 10.0:
            return False
        notice_at[uid] = now
        return True

    def trade_status_noop(message):
        # Normal TeleBot handling completes this update. No API/state action.
        return None

    def active_trade_message_guard(message):
        user_id = int(message.from_user.id)
        if not get_active_player_trade(user_id):
            return ContinueHandling()
        if _trade_is_amount_input_active_12_6_4(user_id):
            return ContinueHandling()
        if notice_allowed(user_id):
            bot.send_message(
                message.chat.id,
                "🤝 Зараз триває обмін.\n\n"
                "Завершіть або скасуйте поточний обмін, перш ніж "
                "виконувати інші дії.",
                reply_markup=player_trade_active_reply_kb_12_6_4(),
            )
        return None

    def active_trade_callback_guard(call):
        user_id = int(call.from_user.id)
        if not get_active_player_trade(user_id):
            return ContinueHandling()
        if _trade_lock_allowed_callback_12_6_4(getattr(call, "data", "")):
            return ContinueHandling()
        if notice_allowed(user_id):
            try:
                bot.answer_callback_query(
                    call.id,
                    "Завершіть або скасуйте поточний обмін.",
                    show_alert=True,
                )
            except Exception:
                pass
        return None

    message_before = len(bot.message_handlers)
    bot.register_message_handler(
        active_trade_message_guard,
        func=lambda message: True,
    )
    bot.register_message_handler(
        trade_status_noop,
