def build_refine_attempt_result_text(user_id, inventory_id, before_info, after_info, result, use_success_rune):
    before_level = int((before_info or {}).get("refine_level", 0) or 0)
    after_level = int((after_info or {}).get("refine_level", 0) or 0)

    before_name = get_inventory_refined_display_name(
        inventory_id,
        (before_info or {}).get("name", "Предмет")
    )

    after_name = get_inventory_refined_display_name(
        inventory_id,
        (after_info or before_info or {}).get("name", "Предмет")
    )

    if not result.get("success"):
        return (
            f"❌ Заточка не виконана.\n\n"
            f"📦 {before_name}\n"
            f"ℹ️ {result.get('message', 'Спроба неможлива.')}"
        )

    if result.get("idempotent_replay"):
        return (
            "ℹ️ Цю спробу заточки вже оброблено.\n\n"
            f"📦 {after_name}\n"
            "Матеріали повторно не списувалися."
        )

    lines = []

    if use_success_rune:
        lines.append("💎 Руна Успіху використана.")
        lines.append("🎯 Шанс успіху був 100%.")

    if after_level > before_level:
        lines.append("✅ Заточка успішна!")
        lines.append("")
        lines.append(f"📦 {after_name}")
        lines.append(f"✨ Було: +{before_level}")
        lines.append(f"✨ Стало: +{after_level}")

        refine_kind = result.get("refine_kind") or can_refine_item(after_info).get("refine_kind", "")

        if refine_kind == "weapon":
            lines.append("⚔️ Шкода збільшена.")
        elif refine_kind == "armor":
            lines.append("🛡️ Бонус до максимального HP збільшено.")

        lines.append("🪨 Камінь Посилення витрачено.")

    elif after_level < before_level:
        lines.append("❌ Заточка не вдалася.")
        lines.append("")
        lines.append(f"📦 {after_name}")
        lines.append(f"📉 Заточка знижена: +{before_level} → +{after_level}")
        lines.append("🪨 Камінь Посилення витрачено.")

    else:
        lines.append("❌ Заточка не вдалася.")
        lines.append("")
        lines.append(f"📦 {after_name}")
        lines.append("✨ Рівень заточки не змінився.")
        lines.append("🪨 Камінь Посилення витрачено.")

    return "\n".join(lines)

def _safe_answer_refine_callback(bot, call, text=None, show_alert=False):
    """Acknowledge refine callbacks while tolerating only expired Telegram queries."""
    try:
        bot.answer_callback_query(call.id, text or "", show_alert=show_alert)
        return True
    except Exception as error:
        message = str(error).lower()
        if "query is too old" in message or "query id is invalid" in message:
            return False
        raise

def build_refine_idempotency_key(user_id, callback_id):
    """One Telegram callback delivery maps to exactly one refine attempt."""
    callback_id = str(callback_id or "").strip()
    if not callback_id:
        raise ValueError("refine callback id is required")
    return f"telegram:refine:{int(user_id)}:{callback_id}"

def build_slot_selection(user_id, equipment_inventory_id, page=0):
    info = get_equipment_rune_slot_info(user_id, equipment_inventory_id)
    if not info.get("success"):
        return info["message"], types.InlineKeyboardMarkup()
    text = (
        "💠 Рунний Майстер\n\n"
        f"⚔️ Спорядження: {info['name']}\n"
        f"📊 Рунні слоти: {info['used']}/{info['capacity']}\n\n"
        "Оберіть порожній слот:"
    )
    keyboard = types.InlineKeyboardMarkup(row_width=1)
    for slot in info["slots"]:
        if slot["occupied"]:
            rune = slot["rune"]
            from data.runes import RUNE_LEVEL_ROMAN, RUNE_STAT_NAMES
            stat_name = RUNE_STAT_NAMES.get(rune["stat"], rune["stat"])
            level_name = RUNE_LEVEL_ROMAN.get(int(rune["level"]), str(rune["level"]))
            label = (
                f"🔒 Слот {slot['display_number']}: "
                f"Руна {stat_name} {level_name}"
            )
            keyboard.add(types.InlineKeyboardButton(text=label, callback_data="rm:locked"))
        else:
            keyboard.add(types.InlineKeyboardButton(
                text=f"▫️ Слот {slot['display_number']}: порожній",
                callback_data=(
                    f"rm:slot:{info['inventory_id']}:{slot['slot_index']}:{int(page)}"
                ),
            ))
    keyboard.add(types.InlineKeyboardButton(
        text="⬅️ До списку спорядження",
        callback_data=f"rm:home:{int(page)}",
    ))
    return text, keyboard

def build_rune_selection(user_id, equipment_inventory_id, slot_index, page=0):
    info = get_equipment_rune_slot_info(user_id, equipment_inventory_id)
    if not info.get("success"):
        return info["message"], types.InlineKeyboardMarkup()
    if not 0 <= int(slot_index) < info["capacity"]:
        return "❌ Рунний слот не існує.", types.InlineKeyboardMarkup()
    runes = get_user_inventory_rune_stacks(user_id)
    text = (
        "💠 Вибір руни\n\n"
        f"⚔️ Спорядження: {info['name']}\n"
        f"▫️ Слот: {int(slot_index) + 1}/{info['capacity']}\n\n"
        "Оберіть руну, яку потрібно вставити у вибраний слот:"
    )
    keyboard = types.InlineKeyboardMarkup(row_width=1)
    for rune in runes:
        quantity = "" if rune["quantity"] == 1 else f" ×{rune['quantity']}"
        keyboard.add(types.InlineKeyboardButton(
            text=_short_name(f"{rune['name']}{quantity}", 52),
            callback_data=(
                f"rm:rune:{equipment_inventory_id}:{int(slot_index)}:"
                f"{rune['inventory_id']}:{int(page)}"
            ),
        ))
    if not runes:
        text += "\n\nℹ️ В інвентарі немає рун характеристик."
    keyboard.add(types.InlineKeyboardButton(
        text="⬅️ До слотів",
        callback_data=f"rm:eq:{equipment_inventory_id}:{int(page)}",
    ))
    return text, keyboard

