def _format_premium_expiration_kyiv(value):
 """Render a UTC string or datetime in the approved Kyiv presentation format."""
 try:
  from datetime import datetime as _datetime, timezone as _timezone
  from zoneinfo import ZoneInfo
  if isinstance(value, _datetime):
   parsed=value
  else:
   parsed=_datetime.fromisoformat(str(value or '').replace('Z','+00:00'))
  if parsed.tzinfo is None:
   parsed=parsed.replace(tzinfo=_timezone.utc)
  return parsed.astimezone(ZoneInfo('Europe/Kyiv')).strftime('%d.%m.%Y %H:%M за Києвом')
 except Exception:
  return 'час завершення невідомий'

def _kyiv_timezone_for_utc(value):
    try:
        return ZoneInfo("Europe/Kyiv")
    except ZoneInfoNotFoundError:
        utc_value = value.astimezone(timezone.utc)
        summer_start = _last_sunday(utc_value.year, 3).replace(hour=1, minute=0, second=0, microsecond=0)
        summer_end = _last_sunday(utc_value.year, 10).replace(hour=1, minute=0, second=0, microsecond=0)
        offset_hours = 3 if summer_start <= utc_value < summer_end else 2
        return timezone(timedelta(hours=offset_hours))

def _world_chronicle_event_text(row):
