        metrics[1]["wins"] += 1; metrics[2]["losses"] += 1
    elif result.winner_id == 2:
        metrics[2]["wins"] += 1; metrics[1]["losses"] += 1
    else:
        metrics[1]["draws"] += 1; metrics[2]["draws"] += 1
