def real_duel(a_cls, b_cls, trials=100, seed=14631):
    catalog = load_production_pvp_skill_catalog()
    wins_a = wins_b = draws = 0
    rounds = []
    totals = {"damage_a":0,"damage_b":0,"healing_a":0,"healing_b":0,"shield_a":0,"shield_b":0,"dot_a":0,"dot_b":0}
