def process_enemy_drops(user_id, mob):

    """Award every active central drop rule once, in canonical order.



    This is the only production composition point after 11.9.0. Compatibility

    functions remain available, but the old nested roll_loot chain is bypassed

    to prevent duplicate equipment, trophy, stone, rune or potion awards.

    """

    from systems.drop_system import get_victory_drop_plan



    messages = []

    rune_result = {"dropped": False}

    executed = []



    for rule_id in get_victory_drop_plan():

        executed.append(rule_id)

        if rule_id == "trophy":

            if "loot_table" in mob and isinstance(mob["loot_table"], list):

                messages.extend(roll_loot_from_loot_table(user_id, mob["loot_table"]))

            elif "loot" in mob and isinstance(mob["loot"], list):

                messages.extend(roll_loot_from_loot_table(user_id, mob["loot"]))

            else:

                messages.extend(roll_loot_from_simple_keys(user_id, mob))

        elif rule_id == "equipment":

            message = roll_equipment_drop(user_id, mob)

            if message:

                messages.append(message)

        elif rule_id == "refine_stone":

            message = roll_refine_stone_drop(user_id, mob)

            if message:

                messages.append(message)

        elif rule_id == "rune":

            try:

                from systems.rune_system import award_rune_drop

                rune_result = award_rune_drop(user_id, mob)

            except Exception as error:

                print(f"⚠️ Rune drop reward failed: {error}")

                rune_result = {"dropped": False, "error": str(error)}

            if rune_result.get("dropped") and rune_result.get("message"):

                messages.append(rune_result["message"])

        elif rule_id == "potion":

            message = roll_potion_drop(user_id, mob)

            if message:

                messages.append(message)

        elif rule_id == "rebirth_sphere":
            message = roll_rebirth_sphere_drop(user_id, mob)
            if message:
                messages.append(message)
        else:

            raise RuntimeError(f"unsupported production victory rule: {rule_id}")



    fatigue_artifact_message = roll_fatigue_artifact_drop(user_id, mob)

    executed.append("fatigue_artifact")

    if fatigue_artifact_message:

        messages.append(fatigue_artifact_message)



    guild_message = _central_guild_elite_reward_11_9_0(user_id, mob)

    if guild_message:

        messages.append(guild_message)



    return {

        "messages": messages,

        "rune_drop": rune_result,

        "executed_rules": tuple(executed),

        "guild_hook_executed": bool(_guild_is_elite_mob_v1(mob)),

    }

def roll_loot(user_id, mob):

    """Compatibility API routed to the final central orchestration."""

    return process_enemy_drops(user_id, mob)["messages"]

def claim_daily_quest_reward_with_firius_tokens(user_id):
    """Atomically claim the base reward plus 5 cumulative Firius Tokens."""
    from data.balance import DAILY_QUEST_REWARD_ITEM_ID, DAILY_QUEST_REWARD_QUANTITY

    db = _db()
    db.reset_daily_quest_if_needed(user_id)
    conn = db.conn
    try:
        conn.execute("BEGIN IMMEDIATE")
        row = conn.execute(
            """
            SELECT progress, target_count, completed, reward_claimed
            FROM user_daily_quests WHERE user_id=?
            """,
            (int(user_id),),
        ).fetchone()
        if not row:
            conn.rollback()
            return {"success": False, "message": "❌ Щоденне завдання не знайдено."}
        progress, target_count, completed, reward_claimed = row
        if not bool(completed):
            conn.rollback()
            return {
                "success": False,
                "message": (
                    "❌ Щоденне завдання ще не виконано.\n\n"
                    f"📈 Прогрес: {int(progress or 0)}/{int(target_count or 0)}"
                ),
            }
        if bool(reward_claimed):
            conn.rollback()
            return {"success": False, "message": "✅ Нагороду за сьогодні вже отримано."}

        base_plan = _plan_stack_addition(
            conn, user_id, DAILY_QUEST_REWARD_ITEM_ID, DAILY_QUEST_REWARD_QUANTITY
        )
        token_plan = _plan_stack_addition(
            conn, user_id, FIRIUS_TOKEN_ITEM_ID, FIRIUS_TOKENS_PER_DAILY_REWARD
        )
        bag_row = conn.execute(
            "SELECT bag_slots FROM users WHERE user_id=?", (int(user_id),)
        ).fetchone()
        used_slots = int(conn.execute(
            "SELECT COUNT(*) FROM inventory WHERE user_id=?", (int(user_id),)
        ).fetchone()[0] or 0)
        capacity = int((bag_row[0] if bag_row else 0) or 0)
        required_slots = base_plan["new_slots"] + token_plan["new_slots"]
        if used_slots + required_slots > capacity:
            conn.rollback()
            return {
                "success": False,
                "code": "bag_full",
                "message": (
                    "🎒 Сумка переповнена.\n\n"
                    "Звільни місце в інвентарі та спробуй забрати нагороду ще раз.\n"
                    "Нічого не було втрачено або частково нараховано."
                ),
            }

        _apply_stack_plan(conn, user_id, base_plan)
        _apply_stack_plan(conn, user_id, token_plan)
        updated = conn.execute(
            "UPDATE user_daily_quests SET reward_claimed=1 "
            "WHERE user_id=? AND completed=1 AND reward_claimed=0",
            (int(user_id),),
        ).rowcount
        if updated != 1:
            raise RuntimeError("Daily reward state changed during claim")
        conn.commit()
        return {
            "success": True,
            "base_item_id": base_plan["item_id"],
            "base_quantity": base_plan["quantity"],
            "firius_token_item_id": FIRIUS_TOKEN_ITEM_ID,
            "firius_token_quantity": FIRIUS_TOKENS_PER_DAILY_REWARD,
            "message": (
                "🎁 Ви отримали нагороду за щоденне завдання!\n\n"
                f"📦 {base_plan['name']} ×{base_plan['quantity']}\n"
                f"🪙 {token_plan['name']} ×{token_plan['quantity']}\n\n"
                "Жетони Фіріуса накопичуються та не зникають наступного дня."
            ),
        }
    except Exception:
        conn.rollback()
        raise

def get_equipment_rune_slot_info(user_id, inventory_id):
    """Return ownership, equipment type, capacity and current socket state."""
    db = _db()
    try:
        inventory_id = int(inventory_id)
        user_id = int(user_id)
    except Exception:
        return {
            "success": False,
            "code": "invalid_id",
            "message": "❌ Некоректний предмет спорядження.",
        }

    row = db.conn.execute(
        """
        SELECT i.id, i.user_id, i.durability, it.name, it.category, it.slot_key
        FROM inventory i
        JOIN items it ON it.id=i.item_id
        WHERE i.id=?
        """,
        (inventory_id,),
    ).fetchone()
    if not row:
        return {
            "success": False,
            "code": "not_found",
            "message": "❌ Предмет не знайдено.",
        }
    if int(row[1]) != user_id:
        return {
            "success": False,
            "code": "not_owner",
            "message": "❌ Цей предмет не належить персонажу.",
        }

    category = str(row[4] or "")
    slot_key = str(row[5] or "")
    capacity = get_rune_slot_limit(slot_key)
    if category != "equipment" or capacity <= 0:
        return {
            "success": False,
            "code": "not_equipment",
            "message": "❌ Руни можна вставляти лише у спорядження з рунними слотами.",
        }

    runes = get_inventory_runes(inventory_id)
    occupied = {int(rune["slot_index"]) for rune in runes}
    slots = []
    for slot_index in range(capacity):
        rune = next(
            (item for item in runes if int(item["slot_index"]) == slot_index),
            None,
        )
        slots.append({
            "slot_index": slot_index,
            "display_number": slot_index + 1,
            "occupied": rune is not None,
            "rune": rune,
        })

    return {
        "success": True,
        "inventory_id": inventory_id,
        "name": str(row[3]),
        "slot_key": slot_key,
        "durability": int(row[2] if row[2] is not None else 100),
        "capacity": capacity,
        "used": len(occupied),
        "free": max(0, capacity - len(occupied)),
        "slots": slots,
    }

