                    "Руни та Жетон Фіріуса не були витрачені."
                ),
            }
        conn.commit()
        return {
            **preview,
            "success": True,
            "code": "fused",
            "message": (
                "✅ Переробку завершено!\n\n"
                f"Витрачено:\n"
                f"• {preview['source_name']} ×3\n"
                "• 🪙 Жетон Фіріуса ×1\n\n"
                f"Отримано:\n• {preview['result_name']} ×1\n\n"
                "Шанс успіху: 100%."
            ),
        }
    except Exception:
        conn.rollback()
        raise

