def build_progression_wall_report(config, payloads):
    levels = []
    for target_level in range(2, config.target_level + 1):
        groups = {}
        for character_class in config.classes:
            groups[character_class] = {}
            for profile in config.profiles:
                specs = [
                    ScenarioSpec(
                        character_class,
                        profile,
                        int(seed),
                        target_level,
                        config.inventory_capacity,
                        config.max_days,
                    )
                    for seed in config.seeds
                ]
                groups[character_class][profile] = aggregate_group([payloads[spec] for spec in specs])
        levels.append({"target_level": target_level, "groups": groups})

    transitions = []
    findings = []
    for character_class in config.classes:
        for profile in config.profiles:
            cumulative_previous = {field: 0.0 for field in DELTA_FIELDS}
            previous_transition = None
            for level_item in levels:
                current = level_item["groups"][character_class][profile]
                transition = _delta(current, cumulative_previous)
                entry = {
                    "class": character_class,
                    "profile": profile,
                    "from_level": level_item["target_level"] - 1,
                    "to_level": level_item["target_level"],
                    "incremental": transition,
                    "cumulative": {field: current.get(field, 0.0) for field in DELTA_FIELDS},
                }
                transitions.append(entry)

                if previous_transition is not None:
                    reasons = []
                    death_pp = transition["mean_deaths"] - previous_transition["mean_deaths"]
                    battle_change = _percentage_change(
                        transition["mean_battles"], previous_transition["mean_battles"]
                    )
                    city_change = transition["mean_city_visits"] - previous_transition["mean_city_visits"]
                    elapsed_change = _percentage_change(
                        transition["mean_elapsed_hours"], previous_transition["mean_elapsed_hours"]
                    )
                    if death_pp >= 0.05:
                        reasons.append(f"incremental deaths +{death_pp:.2f}")
                    if battle_change is not None and battle_change >= 25:
                        reasons.append(f"incremental battles +{battle_change:.1f}%")
                    if elapsed_change is not None and elapsed_change >= 25:
                        reasons.append(f"incremental elapsed time +{elapsed_change:.1f}%")
                    if city_change >= 2:
                        reasons.append(f"incremental city visits +{city_change:.2f}")
                    if reasons:
                        findings.append(
                            {
                                "severity": "REVIEW",
                                "code": "progression_wall",
                                "class": character_class,
                                "profile": profile,
                                "from_level": entry["from_level"],
                                "to_level": entry["to_level"],
                                "reasons": reasons,
                                "current_transition": transition,
                                "previous_transition": previous_transition,
                            }
                        )
                previous_transition = transition
                cumulative_previous = current

    return {
        "schema": "rom.simulation.progression_walls.v2",
        "version": "13.7.2",
        "methodology": "incremental transition deltas, not cumulative totals",
        "target_level": config.target_level,
        "levels": levels,
        "transitions": transitions,
        "findings": findings,
        "database_writes": 0,
    }

def __init__(self, project_root: Path, seed: int, max_turns: int=100):
        self.root=Path(project_root); self.rng=SimulationRng(seed); self.seed=int(seed); self.max_turns=max_turns
        self.skills=load_production_skill_catalog(self.root)

def _effective_def(self, actor: BattleActor, kind: str) -> int:
        value=float(actor.mdef if kind=="magical" else actor.pdef)
        key="mdef_percent" if kind=="magical" else "pdef_percent"
        for effect in actor.effects.values(): value *= 1+float(effect.get(key,0))/100
        return max(0,int(round(value)))

def _absorb(self, player: BattleActor, damage: int) -> int:
        for key,e in list(player.effects.items()):
            if e.get("type")=="shield" and damage>0:
                used=min(damage,int(e.get("absorb_left",0))); damage-=used; e["absorb_left"]-=used
                if e["absorb_left"]<=0: del player.effects[key]
        return damage

def _can_use(self, actor: BattleActor, skill: Dict[str,Any]) -> bool:
        if actor.cooldowns.get(skill["key"],0)>0: return False
        typ=skill["cost_type"]; cost=self._effective_skill_cost(actor, skill)
        if typ=="rage_all_min": return actor.resource>=int(skill.get("min_cost",30))
        if typ=="combat_energy_combo": return actor.resource>=cost and actor.combo>=int(skill.get("min_combo",1))
        return actor.resource>=cost

def _apply_effect(self, player: BattleActor, mob: BattleActor, skill: Dict[str,Any], damage: int):
        effect=skill.get("effect")
        if effect=="enemy_pdef_down": mob.effects["warrior_pdef"]={"turns":3,"pdef_percent":-30}
        elif effect=="enemy_pdef_trap": mob.effects["scout_pdef"]={"turns":2,"pdef_percent":-50}
        elif effect in {"enemy_bleed","enemy_poison"}: mob.effects[effect]={"type":"dot","turns":3,"damage":max(2,int(round(max(1,damage)*.30)))}
        elif effect=="player_shield": player.effects["knight_shield"]={"type":"shield","turns":3,"absorb_left":max(15,int(player.pdef*2+player.level*3))}
        elif effect=="player_hot": player.effects["priest_hot"]={"type":"hot","turns":PRIEST_HEALING_DURATION_TURNS,"heal":max(5,int(round(player.max_hp*.10)))}
        elif effect=="restore_mana_percent": player.resource=min(player.max_resource,player.resource+calculate_mana_restore_amount(player.max_resource,skill.get("restore_max_mp_percent",25)))
        elif effect=="player_cleanse_mdef_buff":
            player.effects={k:v for k,v in player.effects.items() if not v.get("negative")}; player.effects["priest_mdef"]={"turns":3,"mdef_percent":30}
            player.resource=min(player.max_resource,player.resource+calculate_mana_restore_amount(player.max_resource,skill.get("restore_max_mp_percent",15)))

def _player_action(self, turn, class_key, p, m, actions):
        skill=self._choose(class_key,p,m)
        if skill:
            spent=self._pay(p,skill); mult=float(skill.get("damage_multiplier",0)); damage=0; crit=False
            if mult>0:
                attack=p.magic_attack if skill["attack_type"]=="magical" else p.attack
                base=call_rule("player_attack",attack,self._effective_def(m,skill["attack_type"]),p.dex,p.wis,p.level,skill["attack_type"],p.weapon_min_damage,p.weapon_max_damage,rng=self.rng)
                damage=max(1,int(round(int(base["damage"])*mult))); crit=bool(base["is_crit"])
                if skill.get("scales_with_spent_rage"): damage=max(1,int(round(damage*(1+spent["rage"]/100))))
                if skill.get("scales_with_combo"): damage=max(1,int(round(damage*(1+spent["combo"]*.50))))
                if skill.get("scales_with_player_pdef"): damage+=max(1,int(round(p.pdef*.50)))
                m.hp=max(0,m.hp-damage)
            if int(skill.get("stun_chance",0)) and self.rng.randint(1,100)<=int(skill["stun_chance"]): m.effects["stunned"]={"turns":1,"stun":True}
            if int(skill.get("combo_gain",0)): p.combo=min(p.max_combo,p.combo+int(skill["combo_gain"]))
            if int(skill.get("extra_rage",0)): p.resource=min(p.max_resource,p.resource+int(skill["extra_rage"]))
            p.cooldowns[skill["key"]]=int(skill.get("cooldown",0)); self._apply_effect(p,m,skill,damage)
            actions.append(BattleAction(turn,"player",skill["key"],damage=damage,critical=crit,details={"resource":p.resource,"combo":p.combo})); return
        kind=resolve_basic_attack_type(class_key); attack=p.magic_attack if kind=="magical" else p.attack
        raw=call_rule("player_attack",attack,self._effective_def(m,kind),p.dex,p.wis,p.level,kind,p.weapon_min_damage,p.weapon_max_damage,rng=self.rng)
        damage=int(raw["damage"]); m.hp=max(0,m.hp-damage)
        if p.resource_type=="rage": p.resource=min(p.max_resource,p.resource+15)
        actions.append(BattleAction(turn,"player","basic_attack",damage=damage,critical=bool(raw["is_crit"])))

def _safe_run_id(value: str) -> str:
    result = re.sub(r"[^A-Za-z0-9_.-]+", "_", str(value or "simulation"))
    return result.strip("._") or "simulation"

def random(self) -> float:
        self._draw()
        return self._random.random()

def randint(self, a: int, b: int) -> int:
        self._draw()
        return self._random.randint(a, b)

def uniform(self, a: float, b: float) -> float:
        self._draw()
        return self._random.uniform(a, b)

def choice(self, values: Sequence[T]) -> T:
        if not values:
            raise IndexError("cannot choose from an empty sequence")
        self._draw()
        return self._random.choice(values)

def choices(self, values: Sequence[T], weights=None, k: int = 1):
        if not values:
            raise IndexError("cannot choose from an empty sequence")
        self._draw()
        return self._random.choices(values, weights=weights, k=k)

def shuffle(self, values: MutableSequence[Any]) -> None:
        self._draw()
        self._random.shuffle(values)

def choices(self, population: Sequence[T], weights=None, *, cum_weights=None, k: int = 1):
        if cum_weights is not None:
            raise ValueError("cum_weights is not supported by SimulationRng adapter")
        return self.rng.choices(population, weights=weights, k=k)

def _number(value) -> float:
    try:
        return float(value)
    except (TypeError, ValueError):
        return 0.0

def distribution(values: Iterable[float]) -> dict:
    data = [_number(value) for value in values]
    if not data:
        return {"count": 0, "minimum": 0.0, "maximum": 0.0, "mean": 0.0, "median": 0.0, "standard_deviation": 0.0, "coefficient_of_variation": 0.0, "interquartile_range": 0.0, "p05_p95_spread": 0.0, "stability": "UNAVAILABLE", "percentiles": {f"p{p:02d}": 0.0 for p in PERCENTILES}}
    mean = statistics.fmean(data)
    std = statistics.pstdev(data) if len(data) > 1 else 0.0
    cv = abs(std / mean) if mean else (0.0 if std == 0.0 else float("inf"))
    pct = {f"p{p:02d}": round(percentile(data, p), 6) for p in PERCENTILES}
    if cv < 0.05:
        stability = "STABLE"
    elif cv < 0.15:
        stability = "WATCH"
    elif cv < 0.30:
        stability = "REVIEW"
    else:
        stability = "UNSTABLE"
    return {
        "count": len(data),
        "minimum": round(min(data), 6),
        "maximum": round(max(data), 6),
        "mean": round(mean, 6),
        "median": round(statistics.median(data), 6),
        "standard_deviation": round(std, 6),
        "coefficient_of_variation": round(cv, 6) if math.isfinite(cv) else "INF",
        "interquartile_range": round(pct["p75"] - pct["p25"], 6),
        "p05_p95_spread": round(pct["p95"] - pct["p05"], 6),
        "stability": stability,
        "percentiles": pct,
    }

def rng_bands(metric: str, stats: Mapping) -> dict:
    pct = dict(stats.get("percentiles") or {})
    lower_is_better = metric in LOWER_IS_BETTER
    if lower_is_better:
        unlucky, typical, lucky = pct.get("p90", 0.0), pct.get("p50", 0.0), pct.get("p10", 0.0)
    else:
        unlucky, typical, lucky = pct.get("p10", 0.0), pct.get("p50", 0.0), pct.get("p90", 0.0)
    return {"direction": "lower_is_better" if lower_is_better else "higher_is_better", "unlucky": unlucky, "typical": typical, "lucky": lucky}

def load_production_skill_catalog(project_root: Path) -> Dict[str, List[Dict[str, Any]]]:
    path = Path(project_root) / "handlers" / "combat.py"
    tree = ast.parse(path.read_text(encoding="utf-8-sig"), filename=str(path))
    candidates=[]
    for node in tree.body:
        if isinstance(node, ast.Assign):
            for target in node.targets:
                if isinstance(target, ast.Name) and target.id == "CLASS_SKILLS_V1":
                    candidates.append(ast.literal_eval(node.value))
    if len(candidates) != 1:
        raise SkillCatalogError(f"expected one CLASS_SKILLS_V1, found {len(candidates)}")
    catalog=candidates[0]
    required={"warrior","knight","scout","rogue","mage","priest"}
    if set(catalog) != required:
        raise SkillCatalogError(f"class catalog mismatch: {sorted(catalog)}")
    for class_key, skills in catalog.items():
        if len(skills) != 3:
            raise SkillCatalogError(f"{class_key} must have 3 skills")
        for skill in skills:
            for key in ("key","cost_type","cost","cooldown","damage_multiplier","attack_type"):
                if key not in skill:
                    raise SkillCatalogError(f"{class_key} skill missing {key}")
    return deepcopy(catalog)

def equipped_items(self):
        ids={value for value in self.equipment.slots.values() if value is not None}
        return [item for item in self.inventory.items if item.simulation_item_id in ids]

def damage_on_death(self) -> DurabilityResult:
        changed=[];broken=0
        for item in self.equipped_items():
            old=item.durability;item.durability=max(0,old-5)
            if item.durability!=old:changed.append(item.simulation_item_id)
            if old>0 and item.durability==0:broken+=1
        return DurabilityResult(len(changed),broken,changed)

def urgent_repair(self, gold: float, threshold: int=15) -> tuple[float,RepairResult]:
        candidates=[item for item in self.equipped_items() if item.durability<=int(threshold)]
        repaired=[];cost=0.0;skipped=0
        for item in sorted(candidates,key=lambda x:x.simulation_item_id):
            item_cost=float(call_rule("repair_cost",item.durability,item.rarity))
            if gold+1e-9 < item_cost:
                skipped+=1;continue
            gold=round(gold-item_cost,2);cost=round(cost+item_cost,2);item.durability=100;repaired.append(item.simulation_item_id)
        return gold,RepairResult(len(repaired),cost,skipped,repaired)

def _encounter_type(mob: Dict) -> str:
    if bool(mob.get("is_boss")) or str(mob.get("enemy_type", "")).lower() == "boss":
        return "boss"
    if bool(mob.get("is_elite")) or str(mob.get("enemy_type", "")).lower() == "elite":
        return "elite"
    return "normal"

def _number(value) -> float:
    try:
        result = float(value or 0)
    except (TypeError, ValueError):
        return 0.0
    return result

def _calculate_weighted_attack(character_class, matrix, *, strength=0, dexterity=0, intelligence=0, wisdom=0, stamina=0) -> int:
    class_key = str(character_class or "").strip().casefold()
    coefficients = matrix.get(class_key)
    if coefficients is None:
        return 0
    stats = {
        "str": _number(strength),
        "dex": _number(dexterity),
        "int": _number(intelligence),
        "wis": _number(wisdom),
        "sta": _number(stamina),
    }
    raw = sum(stats[key] * coefficients[key] for key in PRIMARY_STAT_KEYS)
    return max(1, int(raw))

def calculate_physical_defense(*, equipment_pdef=0, stamina=0) -> int:
    """Stage 18.14.2: active item PDEF plus total STA at coefficient 0.35."""
    from data.defense_policy import calculate_total_defense

    return int(calculate_total_defense(equipment_pdef, stamina))

def calculate_magical_defense(*, equipment_mdef=0, wisdom=0) -> int:
    """Stage 18.14.2: active item MDEF plus total WIS at coefficient 0.35."""
    from data.defense_policy import calculate_total_defense

    return int(calculate_total_defense(equipment_mdef, wisdom))

def calculate_max_mp(character_class, *, level=0, intelligence=0, wisdom=0) -> int:
    """Return configurable maximum mana for mana classes."""
    class_key = str(character_class or "").strip().casefold()
    if class_key not in MANA_CLASSES:
        return 0
    raw = (
        MAX_MP_SCALING["base"]
        + _number(level) * MAX_MP_SCALING["level"]
        + _number(intelligence) * MAX_MP_SCALING["int"]
        + _number(wisdom) * MAX_MP_SCALING["wis"]
    )
    return max(0, int(raw))

def story_boss_callback_data(action: str, quest_number: int) -> str:
    """Build a versioned callback bound to one production BOSS quest."""
    return f"{CALLBACK_PREFIX}:{str(action)}:{int(quest_number)}"

def parse_story_boss_callback(data: str) -> tuple[StoryBossAction, int] | None:
    parts = str(data or "").split(":")
    if len(parts) != 4 or parts[:2] != ["sqboss", "v1"]:
        return None
    try:
        action = StoryBossAction(parts[2])
        quest_number = int(parts[3])
    except (ValueError, TypeError):
        return None
    return action, quest_number

def evaluate_story_boss_invocation(state: StoryBossInvocationState) -> StoryBossInvocationDecision:
    if state.quest_number not in SUPPORTED_STORY_BOSS_QUESTS:
        return StoryBossInvocationDecision.WRONG_QUEST
    if str(state.quest_status).upper() != "ACTIVE":
        return StoryBossInvocationDecision.QUEST_NOT_ACTIVE
    if state.progress_current >= state.progress_target:
        return StoryBossInvocationDecision.ALREADY_DEFEATED
    if state.current_location_id != state.expected_location_id:
        return StoryBossInvocationDecision.WRONG_LOCATION
    if state.has_active_encounter:
        return StoryBossInvocationDecision.ACTIVE_ENCOUNTER
    if state.has_active_travel:
        return StoryBossInvocationDecision.ACTIVE_TRAVEL
    if state.is_busy:
        return StoryBossInvocationDecision.BUSY
    return StoryBossInvocationDecision.ALLOW

