def get_active_story_boss_call(
    *, user_id: int, current_location_id: str,
    registry: Mapping[str, StoryQuestDefinition] = STORY_QUEST_REGISTRY,
    connection=None,
) -> dict:
    """Return a callable boss contract only for a matching ACTIVE BOSS quest.

    COMPLETED and SKIPPED rows are never callable because only the canonical
    ACTIVE row is considered. Consequently a successful kill, which Stage 19.19
    completes immediately, permanently removes the guaranteed call and prevents
    farming even if a stale Telegram button is pressed later.
    """
    if not registry:
        return {"allowed": False, "reason": "no_production_content"}
    if connection is None:
        import db
        connection = db.conn
    active=get_active_story_quest(connection,int(user_id))
    if active is None:
        return {"allowed":False,"reason":"no_active_quest"}
    quest=registry.get(str(active["quest_id"]))
    if quest is None:
        return {"allowed":False,"reason":"unknown_quest_definition"}
    if quest.quest_type is not QuestType.BOSS:
        return {"allowed":False,"reason":"objective_type_mismatch"}
    if quest.location_id != str(current_location_id):
        return {"allowed":False,"reason":"location_mismatch"}
    if int(active["progress"]) >= int(active["target_quantity"]):
        return {"allowed":False,"reason":"objective_already_complete"}
    # Presentation and callback layers must receive the authoritative active
    # quest identity. Without these fields they fall back to legacy quest 49.
    return {
        "allowed": True,
        "reason": "active_boss_quest",
        "quest_id": quest.quest_id,
        "quest_number": int(quest.number),
        "quest_status": str(active["status"]),
        "progress_current": int(active["progress"]),
        "progress_target": int(active["target_quantity"]),
        "boss_key": quest.boss_key,
        "location_id": quest.location_id,
    }

def process_rng_boss_story_completion(
    *,
    user_id: int,
    mob: dict,
    location_id: str,
    encounter_id,
    registry: Mapping[str, StoryQuestDefinition] = STORY_QUEST_REGISTRY,
    connection=None,
) -> dict:
    """Record a matching ACTIVE BOSS victory without completing the quest.

    Combat reward ownership remains in the combat pipeline. This bridge only
    advances the canonical BOSS objective to its bounded target. The quest stays
    ACTIVE, reward_claimed stays unchanged, and the NPC completion owner later
    completes and rewards the quest after the player reports the victory.

    Repeated delivery of the same terminal victory is idempotent because bounded
    progress is set to the same target. Defeat and escape never call this victory
    bridge, so they leave progress unchanged and allow another invocation.
    """
    if not registry:
        return {"advanced": False, "completed": False, "reason": "no_production_content"}
    if not bool((mob or {}).get("is_boss")):
        return {"advanced": False, "completed": False, "reason": "not_boss"}
    if connection is None:
        import db
        connection = db.conn

    active = get_active_story_quest(connection, int(user_id))
    if active is None:
        return {"advanced": False, "completed": False, "reason": "no_active_quest"}

    quest = registry.get(str(active["quest_id"]))
    if quest is None:
        return {"advanced": False, "completed": False, "reason": "unknown_quest_definition"}
    if quest.quest_type is not QuestType.BOSS:
        return {"advanced": False, "completed": False, "reason": "objective_type_mismatch"}
    if quest.location_id != str(location_id):
        return {"advanced": False, "completed": False, "reason": "location_mismatch"}
    if str(quest.boss_key) != str((mob or {}).get("boss_key") or ""):
        return {"advanced": False, "completed": False, "reason": "boss_key_mismatch"}

    before = int(active["progress"])
    target = int(quest.target_quantity)
    if before >= target:
        return {
            "advanced": False,
            "completed": False,
            "reason": "already_recorded",
            "quest_id": quest.quest_id,
            "progress": before,
            "target_quantity": target,
            "encounter_id": encounter_id,
            "status": str(active["status"]),
            "reward_claimed": int(active["reward_claimed"]),
        }

    with connection:
        row = set_story_quest_progress(
            connection,
            user_id=int(user_id),
            quest_id=quest.quest_id,
            progress=target,
        )

    after = int(row["progress"])
    return {
        "advanced": after > before,
        "completed": False,
        "reason": "progress_recorded" if after > before else "already_recorded",
        "quest_id": quest.quest_id,
        "progress": after,
        "target_quantity": target,
        "encounter_id": encounter_id,
        "status": str(row["status"]),
        "reward_claimed": int(row["reward_claimed"]),
    }

def _definition(registry, quest_id: str) -> StoryQuestDefinition:
    try:
        return registry[str(quest_id)]
    except KeyError as error:
        raise StoryQuestCompletionError(f"unknown story quest: {quest_id}") from error

def _objective_ready(connection, user_id: int, quest, row) -> bool:
    """Evaluate objective and cross-quest prerequisite readiness."""
    for required in quest.required_quest_items:
        quantity = get_total_story_quest_item_quantity(
            connection, user_id, required.item_key
        )
        if quantity < required.quantity:
            return False
    if quest.quest_type is QuestType.QUEST_ITEM:
        if quest.quest_item is None:
            raise StoryQuestCompletionError("QUEST_ITEM definition has no item contract")
        quantity = get_story_quest_item_quantity(
            connection, user_id, quest.quest_id, quest.quest_item.item_key
        )
        return quantity >= quest.quest_item.required_quantity
    if quest.quest_type in {QuestType.KILL_REGION, QuestType.BOSS}:
        return int(row["progress"]) >= int(row["target_quantity"])
    # TALK and TURN_IN become complete when their matching interaction invokes
    # this service. NPC identity is checked by expected_turn_in_npc_id below.
    return quest.quest_type in {QuestType.TALK, QuestType.TURN_IN}

def process_story_quest_item_drop(
    *,
    user_id: int,
    location_id: str,
    registry: Mapping[str, StoryQuestDefinition] = STORY_QUEST_REGISTRY,
    connection=None,
    random_value: Callable[[], float] = random.random,
) -> dict:
    """Roll and grant one dedicated quest item after terminal victory.

    Ordinary inventory, bag capacity, mob identity and ordinary loot tables are
    intentionally excluded. The lifecycle owner rechecks ACTIVE/type/location/
    item-key state and persistence bounds quantity to the definition target.
    """
    if not registry:
        return {"granted": 0, "reason": "no_production_content"}
    if connection is None:
        import db
        connection = db.conn
    active = get_active_story_quest(connection, int(user_id))
    if active is None:
        return {"granted": 0, "reason": "no_active_quest"}
    quest = registry.get(str(active["quest_id"]))
    if quest is None:
        return {"granted": 0, "reason": "unknown_quest_definition"}
    if quest.quest_type is not QuestType.QUEST_ITEM or quest.quest_item is None:
        return {"granted": 0, "reason": "objective_type_mismatch"}
    if quest.location_id != str(location_id):
        return {"granted": 0, "reason": "location_mismatch"}
    current = get_story_quest_item_quantity(
        connection, int(user_id), quest.quest_id, quest.quest_item.item_key
    )
    required = int(quest.quest_item.required_quantity)
    if current >= required:
        return {
            "granted": 0,
            "quantity": current,
            "required_quantity": required,
            "objective_complete": True,
            "reason": "target_reached",
        }
    roll = float(random_value())
    if not 0.0 <= roll < 1.0:
        raise ValueError("random_value must return a value within [0, 1)")
    if roll >= float(quest.quest_item.drop_chance):
        return {
            "granted": 0,
            "quantity": current,
            "required_quantity": required,
            "objective_complete": False,
            "reason": "drop_missed",
        }
    result = collect_active_quest_item(
        connection,
        registry=registry,
        user_id=int(user_id),
        location_id=str(location_id),
        item_key=quest.quest_item.item_key,
        amount=1,
    )
    return {
        **result,
        "item_key": quest.quest_item.item_key,
        "display_name": quest.quest_item.display_name,
        # Presentation metadata is returned only after the canonical bounded
        # grant. Consumers must display it only when granted > 0.
        "drop_message": (f"🧩 Сюжетна знахідка: {quest.quest_item.display_name}" if result.get("granted") else None),
        "reason": "granted" if result.get("granted") else "target_reached",
    }

def resolve_story_quest_player_level(stats: Any, *, default: int = 1) -> int:
    """Return a validated level from canonical stats and row-like objects.

    ``db.get_player_stats`` returns ``(STR, DEX, INT, WIS, STA, level)``.
    Story journal and NPC presentation also accept mapping and object forms.
    """
    fallback = max(1, int(default))
    if stats is None:
        return fallback

    value = None
    if isinstance(stats, (tuple, list)):
        # Canonical positional contract: level is the sixth field.
        value = stats[5] if len(stats) > 5 else fallback
    elif isinstance(stats, Mapping):
        value = stats.get("level", fallback)
    elif hasattr(stats, "keys") and callable(stats.keys):
        try:
            if "level" in stats.keys():
                value = stats["level"]
        except (KeyError, TypeError, IndexError):
            value = None

    if value is None:
        value = getattr(stats, "level", fallback)
    try:
        level = int(value)
    except (TypeError, ValueError):
        return fallback
    return level if level >= 1 else fallback

def reward_adapter(*, connection, user_id, quest, idempotency_key):
        exp_result = apply_exp_in_transaction(connection, user_id, exp_amount)
        if exp_result is None:
            raise ValueError(f"unknown user_id: {user_id}")
        gold_balance = apply_gold_in_transaction(connection, user_id, gold_amount)
        return {
            "quest_id": quest.quest_id,
            "idempotency_key": str(idempotency_key),
            "exp_awarded": exp_amount,
            "gold_awarded": gold_amount,
            "gold_balance": gold_balance,
            "exp_result": exp_result,
        }

def build_story_quest_registry(
    packs: Iterable[Sequence[StoryQuestDefinition]],
) -> Mapping[str, StoryQuestDefinition]:
    """Validate ordered packs and construct one global immutable-style registry.

    Each pack is validated independently. This permits reviewed content batches
    of ten while global checks still prevent duplicate IDs, numbers and broken
    predecessor references across pack boundaries.
    """
    registry = {}
    numbers = {}
    ordered = []
    for pack in packs:
        validated = validate_story_quest_pack(pack)
        for quest in validated.values():
            if quest.quest_id in registry:
                raise StoryQuestLifecycleError(f"duplicate quest_id: {quest.quest_id}")
            if quest.number in numbers:
                raise StoryQuestLifecycleError(f"duplicate quest number: {quest.number}")
            registry[quest.quest_id] = quest
            numbers[quest.number] = quest.quest_id
            ordered.append(quest)
    if not registry:
        raise StoryQuestLifecycleError("story quest registry cannot be empty")
    ordered.sort(key=lambda quest: quest.number)
    for quest in ordered:
        predecessor = quest.previous_quest_id
        if predecessor is None:
            continue
        previous = registry.get(predecessor)
        if previous is None:
            raise StoryQuestLifecycleError(
                f"{quest.quest_id}: predecessor {predecessor} is not registered"
            )
        if previous.number + 1 != quest.number:
            raise StoryQuestLifecycleError(
                f"{quest.quest_id}: predecessor number is not consecutive"
            )
    return dict(registry)

def _definition(registry, quest_id: str) -> StoryQuestDefinition:
    try:
        return registry[str(quest_id)]
    except KeyError as error:
        raise StoryQuestLifecycleError(f"unknown story quest: {quest_id}") from error

def get_story_quest_status(
    connection,
    *,
    user_id: int,
    quest: StoryQuestDefinition,
    player_level: int,
) -> PersistentQuestStatus | DerivedQuestStatus:
    """Resolve persistent status first, otherwise derive LOCKED or AVAILABLE."""
    row = get_story_quest(connection, user_id, quest.quest_id)
    if row is not None:
        return PersistentQuestStatus(str(row["status"]))

    predecessor_completed = quest.previous_quest_id is None
    if quest.previous_quest_id is not None:
        predecessor = get_story_quest(connection, user_id, quest.previous_quest_id)
        predecessor_completed = bool(
            predecessor and predecessor["status"] in (PersistentQuestStatus.COMPLETED.value, PersistentQuestStatus.SKIPPED.value)
        )
    another_active = get_active_story_quest(connection, user_id) is not None
    if (
        int(player_level) < int(quest.unlock_level)
        or not predecessor_completed
        or another_active
    ):
        return DerivedQuestStatus.LOCKED
    return DerivedQuestStatus.AVAILABLE

def advance_region_kill_progress(
    connection,
    *,
    registry: Mapping[str, StoryQuestDefinition],
    user_id: int,
    location_id: str,
    amount: int = 1,
    timestamp: Optional[str] = None,
) -> dict:
    """Atomically advance the matching ACTIVE KILL_REGION objective.

    The caller supplies only the location and count. No concrete normal-mob ID
    is accepted, preserving the region-wide objective policy.
    """
    delta = int(amount)
    if delta <= 0:
        raise ValueError("amount must be positive")
    with immediate_transaction(connection):
        active = get_active_story_quest(connection, user_id)
        if active is None:
            return {"advanced": 0, "reason": "no_active_quest"}
        quest = _definition(registry, active["quest_id"])
        if quest.quest_type is not QuestType.KILL_REGION:
            return {"advanced": 0, "reason": "objective_type_mismatch"}
        if quest.location_id != str(location_id):
            return {"advanced": 0, "reason": "location_mismatch"}
        before = int(active["progress"])
        row = set_story_quest_progress(
            connection,
            user_id=user_id,
            quest_id=quest.quest_id,
            progress=before + delta,
            timestamp=timestamp,
        )
        return {
            "advanced": int(row["progress"]) - before,
            "progress": int(row["progress"]),
            "target_quantity": int(row["target_quantity"]),
            "objective_complete": int(row["progress"]) >= int(row["target_quantity"]),
        }

def reconcile_overlevel_story_locations(
    connection,
    *,
    registry: Mapping[str, StoryQuestDefinition],
    user_id: int,
    current_level: int,
    location_max_levels: Mapping[str, int],
    timestamp: Optional[str] = None,
) -> dict:
    """Atomically SKIP all unfinished quests of every exceeded story location."""
    locations = {}
    for quest in registry.values():
        locations.setdefault(str(quest.location_id), []).append(quest)
    exceeded = []
    for location_id, quests in locations.items():
        if location_id not in location_max_levels:
            raise StoryQuestLifecycleError(f"missing max level for location {location_id}")
        if int(current_level) > int(location_max_levels[location_id]):
            exceeded.append((min(q.number for q in quests), location_id, quests))
    summaries = []
    with immediate_transaction(connection):
        for _, location_id, quests in sorted(exceeded):
            summary = reconcile_story_location_as_skipped(
                connection, user_id=int(user_id), quests=quests, timestamp=timestamp,
            )
            summary.update({"location_id": location_id,
                            "level_ceiling": int(location_max_levels[location_id])})
            summaries.append(summary)
    return {"changed": sum(x["skipped_now"] for x in summaries),
            "locations": summaries, "current_level": int(current_level)}

